= PetalburgWoods_EventScript_DevonResearcherRight
lockall
call PetalburgWoods_EventScript_DevonResearcherIntro
applymovement LOCALID_PETALBURG_WOODS_DEVON_EMPLOYEE PetalburgWoods_Movement_DevonResearcherApproachPlayerRight
waitmovement 0
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
msgbox	Hallo, hast du hier irgendwo ein POKéMON namens SHROOMISH gesehen?Ich liebe dieses POKéMON wirklich.
closemessage
playbgm MUS_ENCOUNTER_AQUA FALSE
applymovement LOCALID_PETALBURG_WOODS_GRUNT PetalburgWoods_Movement_AquaEntrance
waitmovement 0
msgbox	Ich wollte dir eigentlich auflauern, aber du musstest ja ewig in PETALBURG WOODS trödeln, was?Ich hatte es satt zu warten, also bin ich jetzt hier!
closemessage
applymovement LOCALID_PETALBURG_WOODS_GRUNT PetalburgWoods_Movement_AquaApproachResearcherRight
waitmovement 0
applymovement LOCALID_PETALBURG_WOODS_DEVON_EMPLOYEE Common_Movement_WalkInPlaceFasterUp
waitmovement 0
msgbox	Du! DEVON-FORSCHER!Her mit diesen Papieren!
closemessage
applymovement LOCALID_PETALBURG_WOODS_DEVON_EMPLOYEE PetalburgWoods_Movement_DevonResearcherFleeToPlayerRight
waitmovement 0
msgbox	Aiyeeeh!Du bist doch ein POKéMON TRAINER, oder? Du musst mir helfen, bitte!
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterUp
waitmovement 0
msgbox	Hunh? Was glaubst du eigentlich, was du da machst? Was, du willst ihn beschützen?Wer sich mit TEAM AQUA anlegt, bekommt keine Gnade, nicht mal ein Kind!Los, kämpf gegen mich!
trainerbattle_no_intro TRAINER_GRUNT_PETALBURG_WOODS PetalburgWoods_Text_YoureKiddingMe
applymovement LOCALID_PETALBURG_WOODS_GRUNT PetalburgWoods_Movement_AquaBackOff
waitmovement 0
call PetalburgWoods_EventScript_DevonResearcherPostBattle
applymovement LOCALID_PLAYER PetalburgWoods_Movement_WatchResearcherLeave
applymovement LOCALID_PETALBURG_WOODS_DEVON_EMPLOYEE PetalburgWoods_Movement_DevonResearcherExitRight
waitmovement 0
goto PetalburgWoods_EventScript_RemoveDevonResearcher
end
= PetalburgWoods_EventScript_RemoveDevonResearcher
removeobject LOCALID_PETALBURG_WOODS_DEVON_EMPLOYEE
setvar VAR_PETALBURG_WOODS_STATE 1
releaseall
end
= PetalburgWoods_EventScript_DevonResearcherPostBattle
msgbox	Grrr… Du hast vielleicht Nerven, dich mit TEAM AQUA anzulegen! Los, kämpf nochmal gegen mich!So gern ich das sagen würde, aber mir sind die POKéMON ausgegangen…Und, hey, wir von TEAM AQUA sind auch hinter etwas in RUSTBORO her.Heute lass ich dich noch laufen!
closemessage
applymovement LOCALID_PETALBURG_WOODS_GRUNT PetalburgWoods_Movement_AquaRunAway
waitmovement 0
removeobject LOCALID_PETALBURG_WOODS_GRUNT
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterDown
waitmovement 0
msgbox	Puh… Das war aber wirklich knapp!Dank dir hat er mir diese wichtigen Papiere nicht gestohlen.Ich weiß, ich geb dir einen GREAT BALL als Dank!
giveitem ITEM_GREAT_BALL
goto_if_eq VAR_RESULT FALSE PetalburgWoods_EventScript_BagFull
goto PetalburgWoods_EventScript_DevonResearcherFinish
end
= PetalburgWoods_EventScript_DevonResearcherFinish
msgbox	Hat dieser TEAM-AQUA-Schläger nicht gesagt, dass sie auch hinter etwas in RUSTBORO her sind?
applymovement LOCALID_PETALBURG_WOODS_DEVON_EMPLOYEE PetalburgWoods_Movement_DevonResearcherStartExit
waitmovement 0
msgbox	Uh-oh! Das ist eine Krise! Ich kann keine Zeit verlieren!
closemessage
return
= PetalburgWoods_EventScript_BagFull
msgbox	Du bist voll bepackt mit Items. Ich kann dir diesen GREAT BALL nicht geben.
goto PetalburgWoods_EventScript_DevonResearcherFinish
end
= PetalburgWoods_EventScript_DevonResearcherIntro
