= EventScript_CutTree
lockall
goto_if_unset FLAG_BADGE01_GET EventScript_CheckTreeCantCut
checkpartymove MOVE_CUT
goto_if_eq VAR_RESULT PARTY_SIZE EventScript_CheckTreeCantCut
setfieldeffectargument 0 VAR_RESULT
bufferpartymonnick STR_VAR_1 VAR_RESULT
buffermovename STR_VAR_2 MOVE_CUT
msgboxyesno	Dieser Baum sieht so aus, als könnte man ihn mit ZERSCHNEIDER fällen! Möchtest du ZERSCHNEIDER einsetzen?
goto_if_eq VAR_RESULT NO EventScript_CancelCut
msgbox	STR_VAR_1 setzt STR_VAR_2 ein!
closemessage
dofieldeffect FLDEFF_USE_CUT_ON_TREE
waitstate
goto EventScript_CutTreeDown
end
@ Use cut from party menu
goto EventScript_UseCut
= EventScript_UseCut
lockall
dofieldeffect FLDEFF_USE_CUT_ON_TREE
waitstate
goto EventScript_CutTreeDown
end
= EventScript_CutTreeDown
applymovement VAR_LAST_TALKED Movement_CutTreeDown
waitmovement 0
removeobject VAR_LAST_TALKED
releaseall
end
= EventScript_CancelCut
closemessage
releaseall
end
= EventScript_CheckTreeCantCut
msgbox	Dieser Baum sieht so aus, als könnte man ihn mit ZERSCHNEIDER fällen!
releaseall
end
signs
14 32	TRAINER TIPSJedes POKéMON, das auch nur einmal in einem Kampf erscheint, erhält EXP-Punkte.Um ein schwaches POKéMON aufzuziehen, stell es ganz links in die Teamliste.Sobald ein Kampf beginnt, wechsle es sofort aus. Es erhält EXP-Punkte, ohne dabei Schaden zu nehmen.
11 8	TRAINER TIPSNeben Hit Points (HP) haben POKéMON auch Power Points (PP), die für Attacken im Kampf verbraucht werden.Wenn einem POKéMON die PP ausgehen, muss es zu einem POKéMON CENTER gebracht werden.
